-- ============================================================
-- 2. Sell-in de Panquecitas (2087 filas, 39.51 Ton)
-- ============================================================
-- REAL: los kg son exactamente los del reporte.
-- 
-- Lo único movido son las fechas: las columnas ene-26..abr-26 se cargan
-- como jun/jul/ago/sep-26 para que la serie termine sobre las ventanas de
-- ronda (10 ago – 25 sep 26) y el dashboard no muestre data de hace medio
-- año. Se conservan 4 meses distintos porque la Tasa de Recompra cuenta
-- PDV con compras en 2 o más meses calendario.
-- 
-- Alimenta: Total Ton, Running de Ventas, Evolución de Penetración y
-- Recompra, y las columnas de penetración/recompra del Detalle de Clientes.

