-- ============================================================
-- 3. Sell-in de Harina PAN (2913 filas, SIMULADO)
-- ============================================================
-- NO viene en el reporte de Panquecitas. Se genera porque las columnas
-- "% HPM vs Base" y "% HPM TOTAL" del Detalle de Clientes se calculan
-- contra el Sell-in de Harina PAN del mismo PDV; sin esto quedan en 0%.
-- 
-- El volumen parte de un típico por formato de PDV (una bodega mueve ~55
-- kg/mes, un hipermercado ~2.400) y se escala por la columna "Relevancia
-- Interna para EP" que sí trae el reporte, más ruido por cliente y mes.
-- Van los mismos 4 meses que Panquecitas porque el dashboard también
-- grafica el ratio Panquecitas/Harina PAN mes a mes.
-- 
-- Es data de relleno para que la tabla se vea, no una estimación real.

delete from public.sap_sell_in_records where upload_batch_id = 'aa000000-0000-4000-8000-000000000002';

