-- ============================================================
-- 4. Despachos con presentación 400g / 800g (3975 filas)
-- ============================================================
-- Este es el bloque que agrega la presentación: el reporte entrega kg
-- agregados por mes, sin SKU ni fecha de despacho, y sap_sell_in_records
-- no tiene columna de presentación. sap_dispatches sí (variant_id), y es
-- la tabla que lee el motor de Sell-Out.
-- 
-- SIMULADO: el ritmo real de cada cliente (su promedio mensual del
-- reporte) se reparte en tramos de ~2 semanas ubicados entre visitas
-- consecutivas, y cada tramo se desglosa en 400g/800g según el mix típico
-- de su tipo de cliente: bodegas y panaderías cargan sobre todo 400g
-- (ticket bajo del canal tradicional), supermercados e hipermercados se
-- inclinan al 800g. En volúmenes muy chicos el despacho sale de una sola
-- presentación, como pasa en la bodega que compra media docena. Un ~12%
-- de los ciclos queda sin reposición.
-- 
-- quantity va en KG (el motor la resta contra inventario en kg).
-- Los PDV marcados Reportado_B2B no van aquí: reportan su propia venta.
-- 
-- Alimenta: Mix de Producto, Sell-In vs Sell-Out por ronda y Rotación.

delete from public.sap_dispatches where upload_batch_id = 'aa000000-0000-4000-8000-000000000003';

insert into public.sap_dispatches
  (upload_batch_id, location_id, variant_id, quantity, dispatch_date)
