-- ============================================================
-- 7. Visitas de mercaderista (1867 visitas, 544 PDV)
-- ============================================================
-- TODO ESTE BLOQUE ES SIMULADO: no sale del reporte SAP.
-- 
-- Hace falta porque el motor de Sell-Out despeja
--   Sell-Out = Inventario_R1 + Sell_in(R1,R2) − Inventario_R2
-- así que sin inventario por ronda los gráficos de Mix de Producto,
-- Sell-In vs Sell-Out y Rotación quedan vacíos aunque los despachos del
-- bloque 4 estén cargados.
-- 
-- Cobertura parcial a propósito: 544 de 769 PDV, y no todos en
-- las 4 rondas, para que Cobertura y Comunicación no dé una línea plana en
-- 100%. Los precios caen sobre el PVP sugerido en ~46% de los casos y se
-- desvían en el resto, para que el Índice Tienda Ideal dé un valor medio.
-- 
-- Si más adelante cargas visitas reales de estas fechas, borra este bloque:
-- el DELETE de arriba limpia todo el rango de rondas antes de insertar.

-- inventory_audits cae solo por ON DELETE CASCADE del visit_id.
delete from public.mercaderista_visits
where created_at >= '2026-08-10'
  and created_at < '2026-09-26';

insert into public.mercaderista_visits
  (id, location_id, worker_first_name, worker_last_name, worker_cedula,
   pop_present, product_present, product_location, front_faces, deposit_access,
   pop_message, pop_price_tag, pop_materials, price_400, price_400_na,
   price_800, price_800_na, total_units_anaquel, anaquel_400_units,
   anaquel_800_units, harina_trigo_faces, created_at)
select
  v.id::uuid, l.id,
  -- Mercaderista del roster autorizado (migración 003) según el sector.
  case l.oficina_venta when 'CUMANA' then 'Isabella' else 'Mikhaela' end,
  case l.oficina_venta when 'CUMANA' then 'Maggio'   else 'Barboza'  end,
  case l.oficina_venta when 'CUMANA' then '1234'     else '29611053' end,
  v.pop_present, v.product_present,
  case v.ubicacion
    when 'HT'    then ARRAY['HARINA_TRIGO']
    when 'OC'    then ARRAY['OTRA_CATEGORIA']
    when 'HT+OC' then ARRAY['HARINA_TRIGO','OTRA_CATEGORIA']
  end::text[],
  v.front_faces, v.deposit_access, v.pop_message, v.pop_price_tag,
  case v.materiales
    when 'AF'    then ARRAY['AFICHE']
    when 'AF+CO' then ARRAY['AFICHE','COLGANTE']
  end::text[],
  v.price_400, v.na_400, v.price_800, v.na_800,
  v.anaquel_400 + v.anaquel_800, v.anaquel_400, v.anaquel_800,
  v.harina_faces, v.created_at::timestamptz
from (values
  ('7a2baeb5-e2df-4be6-88e1-1e177a6547af', '103122', true, true, 'HT', 7, false, 'ALIMENTA_IDEAS', true, 'AF', 1.2, false, 2.2, false, 1, 0, 9, '2026-08-12 17:06'),
  ('029ec2a6-b10e-4e8b-8a02-c308f39ebf0a', '103122', true, true, 'HT', 2, false, 'ALIMENTA_IDEAS', false, 'AF+CO', 1.37, false, 2.2, false, 1, 0, 2, '2026-08-25 17:17'),
  ('c45a49ec-e330-4e17-8d99-d43f2a5e41fd', '103122', true, true, 'OC', 5, false, 'SIEMPRE_GANAS', true, 'AF', 1.36, false, null::numeric, true, 1, 0, 0, '2026-09-11 11:09'),
