) as v(id, sap_code, pop_present, product_present, ubicacion, front_faces,
       deposit_access, pop_message, pop_price_tag, materiales, price_400,
       na_400, price_800, na_800, anaquel_400, anaquel_800, harina_faces,
       created_at)
join public.locations l on l.sap_code = v.sap_code;

insert into public.mercaderista_visits
  (id, location_id, worker_first_name, worker_last_name, worker_cedula,
   pop_present, product_present, product_location, front_faces, deposit_access,
   pop_message, pop_price_tag, pop_materials, price_400, price_400_na,
   price_800, price_800_na, total_units_anaquel, anaquel_400_units,
   anaquel_800_units, harina_trigo_faces, created_at)
select
  v.id::uuid, l.id,
  -- Mercaderista del roster autorizado (migración 003) según el sector.
  case l.oficina_venta when 'CUMANA' then 'Isabella' else 'Mikhaela' end,
  case l.oficina_venta when 'CUMANA' then 'Maggio'   else 'Barboza'  end,
  case l.oficina_venta when 'CUMANA' then '1234'     else '29611053' end,
  v.pop_present, v.product_present,
  case v.ubicacion
    when 'HT'    then ARRAY['HARINA_TRIGO']
    when 'OC'    then ARRAY['OTRA_CATEGORIA']
    when 'HT+OC' then ARRAY['HARINA_TRIGO','OTRA_CATEGORIA']
  end::text[],
  v.front_faces, v.deposit_access, v.pop_message, v.pop_price_tag,
  case v.materiales
    when 'AF'    then ARRAY['AFICHE']
    when 'AF+CO' then ARRAY['AFICHE','COLGANTE']
  end::text[],
  v.price_400, v.na_400, v.price_800, v.na_800,
  v.anaquel_400 + v.anaquel_800, v.anaquel_400, v.anaquel_800,
